16	var sgrRe = regexp.MustCompile("\x1b\\[([0-9;:]*)m")
17	
18	// underlineMap returns, for each visible rune of s, whether an underline is
19	// active when it is drawn.
20	func underlineMap(s string) (runes []rune, underlined []bool) {
21		on := false
22		pos := 0
23		emit := func(text string) {
24			for _, r := range text {
25				runes = append(runes, r)
26				underlined = append(underlined, on)
27			}
28		}
29		for _, m := range sgrRe.FindAllStringSubmatchIndex(s, -1) {
30			emit(s[pos:m[0]])
31			pos = m[1]
32			params := s[m[2]:m[3]]
33			if params == "" {
34				on = false
35				continue
36			}
37			for _, p := range strings.Split(params, ";") {
38				switch p {
39				case "0", "24", "4:0":
40					on = false
41				case "4", "4:1", "4:2", "4:3", "4:4", "4:5":
42					on = true
43				}
44			}
45		}
46		emit(s[pos:])
47		return runes, underlined
48	}
49	
50	func TestInvalidFieldColorContrastsWithBackground(t *testing.T) {
51		eachShippedTheme(t, func(t *testing.T, name string) {
52			if ColorInvalidField == nil {
53				t.Fatalf("theme %s: ColorInvalidField is not set by ApplyTheme", name)
54			}
55			ratio, err := ContrastRatio(ColorInvalidField, ColorBackground)
56			if err != nil {
57				t.Fatalf("theme %s: %v", name, err)
58			}
59			if ratio < 3.0 {
60				t.Errorf("theme %s: ColorInvalidField on ColorBackground is %.2f:1, want >= 3:1", name, ratio)
61			}
62		})
63	}
64	
65	func TestStyleInvalidFieldFallsBackToASingleUnderline(t *testing.T) {
66		if ColorInvalidField == nil {
67			t.Fatal("ColorInvalidField is not set")
68		}
69		base := lipgloss.NewStyle().Background(ColorBackground).Foreground(ColorText)
70		out := StyleInvalidField(base).Render("x")
71	
72		r, g, b, _ := ColorInvalidField.RGBA()
73		wantUC := fmt.Sprintf("58;2;%d;%d;%d", r>>8, g>>8, b>>8)
74	
75		found := false
76		for _, m := range sgrRe.FindAllStringSubmatch(out, -1) {
77			params := strings.Split(m[1], ";")
78			plain, curly := -1, -1
79			for i, p := range params {
80				switch p {
81				case "4":
82					if plain < 0 {
83						plain = i
84					}
85				case "4:3":
86					curly = i
87				}
88			}
89			if plain < 0 || curly < 0 {
90				continue
91			}
92			found = true
93			if plain > curly {
94				t.Errorf("single underline (4) must come before 4:3, got %q", m[1])
95			}
96			if !strings.Contains(m[1], wantUC) {
97				t.Errorf("sequence %q lacks the underline colour %q (SGR 58)", m[1], wantUC)
98			}
99		}
100		if !found {
101			t.Errorf("no SGR sequence holds both 4 and 4:3 in %q", out)
102		}
103	}
