105	func TestStyleInvalidFieldAddsNoCell(t *testing.T) {
106		if ColorInvalidField == nil {
107			t.Fatal("ColorInvalidField is not set")
108		}
109		base := lipgloss.NewStyle().Background(ColorBackground).Foreground(ColorText)
110		for _, text := range []string{"80a0", "my app", ""} {
111			t.Run(fmt.Sprintf("%q", text), func(t *testing.T) {
112				plain := base.Render(text)
113				invalid := StyleInvalidField(base).Render(text)
114				if got, want := lipgloss.Width(invalid), lipgloss.Width(plain); got != want {
115					t.Errorf("width = %d, want %d", got, want)
116				}
117				if got, want := ansi.Strip(invalid), ansi.Strip(plain); got != want {
118					t.Errorf("text = %q, want %q", got, want)
119				}
120			})
121		}
122		// A non-empty value must really be underlined, or the cases above prove nothing.
123		if !strings.Contains(StyleInvalidField(base).Render("80a0"), "4:3") {
124			t.Error("StyleInvalidField does not underline")
125		}
126	}
