129		if ColorInvalidField == nil {
130			t.Fatal("ColorInvalidField is not set")
131		}
132		base := lipgloss.NewStyle().Background(ColorBackground).Foreground(ColorText)
133		out := StyleInvalidField(base).Render("a b")
134		runes, ul := underlineMap(out)
135		if string(runes) != "a b" {
136			t.Fatalf("visible text = %q, want %q", string(runes), "a b")
137		}
138		want := []bool{true, false, true}
139		for i := range want {
140			if ul[i] != want[i] {
141				t.Errorf("rune %q underlined = %v, want %v", runes[i], ul[i], want[i])
142			}
143		}
144		// The space keeps the theme background.
145		br, bgc, bb, _ := ColorBackground.RGBA()
146		wantBg := fmt.Sprintf("48;2;%d;%d;%d", br>>8, bgc>>8, bb>>8)
147		idx := strings.Index(out, " ")
148		start := strings.LastIndex(out[:idx], "\x1b[")
149		if start < 0 || !strings.Contains(out[start:idx], wantBg) {
150			t.Errorf("the space lost the background %q: %q", wantBg, out[max(start, 0):idx])
151		}
152	}
