131		}
132		base := lipgloss.NewStyle().Background(ColorBackground).Foreground(ColorText)
133		out := StyleInvalidField(base).Render("a b")
134		runes, ul := underlineMap(out)
135		if string(runes) != "a b" {
136			t.Fatalf("visible text = %q, want %q", string(runes), "a b")
137		}
138		want := []bool{true, false, true}
139		for i := range want {
140			if ul[i] != want[i] {
141				t.Errorf("rune %q underlined = %v, want %v", runes[i], ul[i], want[i])
