22	// hexColor matches a string literal that is a whole colour, "#rgb" to "#rrggbbaa".
23	var hexColor = regexp.MustCompile(`^#([0-9a-fA-F]{3}|[0-9a-fA-F]{4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$`)
