64			scan func(string, *ast.File, *token.FileSet) []guardFinding
65			want int
66		}{
67			{"hex literal in a view", "internal/ui/foo/view.go",
68				"package foo\nvar c = lipgloss.Color(\"#ff0000\")\n", findHexColors, 1},
69			{"short hex literal in a view", "internal/ui/foo/view.go",
70				"package foo\nvar c = \"#f00\"\n", findHexColors, 1},
71			{"hex literal in colors.go", "internal/ui/theme/colors.go",
