76				"package foo\nfunc f() { x.UnderlineStyle(1) }\n", findUnderlineUses, 1},
77			{"plain Underline in a view", "internal/ui/foo/view.go",
78				"package foo\nfunc f() { lipgloss.NewStyle().Underline(true) }\n", findUnderlineUses, 1},
