99	func findHexColors(path string, file *ast.File, fset *token.FileSet) []guardFinding {
100		slash := filepath.ToSlash(path)
101		for _, ok := range hexAllowed {
102			if strings.HasSuffix(slash, ok) {
103				return nil
104			}
105		}
106		var out []guardFinding
107		ast.Inspect(file, func(n ast.Node) bool {
108			lit, ok := n.(*ast.BasicLit)
109			if !ok || lit.Kind != token.STRING {
110				return true
111			}
112			s, err := strconv.Unquote(lit.Value)
113			if err == nil && hexColor.MatchString(s) {
114				out = append(out, guardFinding{fset.Position(lit.Pos()),
115					"colour literal " + lit.Value + " outside theme/colors.go (Rule 119): add it to the palette and use the theme name"})
116			}
117			return true
118		})
119		return out
120	}
