122	// findUnderlineUses reports every selector of the underline API that is not
123	// inside theme.StyleInvalidField.
124	func findUnderlineUses(path string, file *ast.File, fset *token.FileSet) []guardFinding {
125		slash := filepath.ToSlash(path)
126		var out []guardFinding
127		report := func(sel *ast.SelectorExpr) {
128			out = append(out, guardFinding{fset.Position(sel.Sel.Pos()),
129				sel.Sel.Name + " used outside theme.StyleInvalidField: call theme.StyleInvalidField instead"})
130		}
131		for _, decl := range file.Decls {
132			inEntry := false
133			if fn, ok := decl.(*ast.FuncDecl); ok {
134				inEntry = fn.Name.Name == underlineFunc && strings.HasSuffix(slash, underlineFile)
135			}
136			if inEntry {
137				continue
138			}
139			ast.Inspect(decl, func(n ast.Node) bool {
140				if sel, ok := n.(*ast.SelectorExpr); ok && strings.HasPrefix(sel.Sel.Name, "Underline") ||
141					ok && strings.HasPrefix(sel.Sel.Name, "GetUnderline") {
142					report(sel)
143				}
144				return true
145			})
146		}
147		return out
148	}
