150	func forEachGuardedFile(t *testing.T, visit func(path string, file *ast.File, fset *token.FileSet)) {
151		t.Helper()
152		seen := map[string]bool{}
153		for _, root := range guardRoots {
154			err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
155				if err != nil {
156					return err
157				}
158				if d.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
159					return nil
160				}
161				abs, err := filepath.Abs(path)
162				if err != nil || seen[abs] {
163					return err
164				}
165				seen[abs] = true
166				fset := token.NewFileSet()
167				file, err := parser.ParseFile(fset, path, nil, parser.SkipObjectResolution)
168				if err != nil {
169					t.Fatalf("parse %s: %v", path, err)
170				}
171				visit(path, file, fset)
172				return nil
173			})
174			if err != nil {
175				t.Fatalf("walk %s: %v", root, err)
176			}
177		}
178		if len(seen) == 0 {
179			t.Fatal("no sources were scanned; the guard would pass on an empty set")
180		}
181	}
